import assert from "node:assert";

const TTL_MS = 60_000;
const cache = new Map();
let calls = 0;
let fail = false;

async function fetchProfile(id) {
  calls++;
  if (fail) throw new Error("upstream down");
  return { id, n: calls };
}

function getProfile(id) {
  const hit = cache.get(id);
  if (hit && hit.expires > Date.now()) return hit.value;
  const value = fetchProfile(id).catch((err) => {
    if (cache.get(id)?.value === value) cache.delete(id);
    throw err;
  });
  cache.set(id, { value, expires: Date.now() + TTL_MS });
  return value;
}

const invalidateProfile = (id) => cache.delete(id);

await Promise.all([getProfile("1"), getProfile("1")]);
assert.equal(calls, 1);
invalidateProfile("1");
await getProfile("1");
assert.equal(calls, 2);
fail = true;
await assert.rejects(getProfile("2"));
fail = false;
await getProfile("2");
