```ts
// profileCache.ts
import { fetchProfile, type Profile } from "./profiles"; // your existing loader

const TTL_MS = 60_000;
const cache = new Map<string, { value: Promise<Profile>; expires: number }>();

// chisle: unbounded per-process Map; LRU cap if user count is large, Redis if >1 instance
export function getProfile(id: string): Promise<Profile> {
  const hit = cache.get(id);
  if (hit && hit.expires > Date.now()) return hit.value;

  // Cache the promise, not the result: concurrent misses share one fetch.
  const value = fetchProfile(id).catch((err) => {
    if (cache.get(id)?.value === value) cache.delete(id); // don't cache failures
    throw err;
  });
  cache.set(id, { value, expires: Date.now() + TTL_MS });
  return value;
}

// Call from every profile write path.
export const invalidateProfile = (id: string) => cache.delete(id);
```

Check, with `fetchProfile` stubbed to count calls:

```ts
await Promise.all([getProfile("1"), getProfile("1")]);
assert.equal(calls, 1); // deduped
invalidateProfile("1");
await getProfile("1");
assert.equal(calls, 2); // refetched after invalidation
```

Security caveat: the key is the profile ID only. If the response varies by viewer (private fields, admin view), key on `${viewerId}:${id}` or cache only the public projection; otherwise one user's view gets served to another.

Staleness: up to 60s on any write path that misses `invalidateProfile`. With more than one instance, invalidation doesn't reach the others → Redis then.

